package com.waqf.awrad.data

import kotlinx.serialization.Serializable

/** The whole content bundle shipped in assets/azkar.json (generated by tools/build_content.py). */
@Serializable
data class Library(
    val version: Int = 1,
    val book: Book = Book(),
    val categories: List<Category> = emptyList(),
)

@Serializable
data class Book(
    val title: String = "",
    val author: String = "",
)

/** One chapter of the book, shown in the app under a friendly title (e.g. «ذكر من تعارّ من الليل»). */
@Serializable
data class Category(
    val id: String,
    val title: String,
    val bookTitle: String = "",
    val page: Int = 0,
    /** Optional key for the quick-access tiles on the home screen (morning_evening, sleep, wake, prayer, …). */
    val featured: String? = null,
    val items: List<Item> = emptyList(),
)

/**
 * A single entry. For a hadith, [zikr] is the exact wording to be said (a verbatim excerpt of [matn]),
 * [fadl] the virtue stated in the hadith, and [isnad]/[source]/[takhrij] stay hidden until the reader asks.
 */
@Serializable
data class Item(
    val id: String,
    val type: String = TYPE_HADITH,
    val num: Int? = null,
    val page: Int = 0,
    val subheading: String = "",
    val zikr: String = "",
    val count: Int = 0,
    val fadl: String = "",
    val matn: String = "",
    val isnad: String = "",
    val source: String = "",
    val extra: String = "",
    val grade: String = "",
    val takhrij: String = "",
    val notes: List<String> = emptyList(),
    val text: String = "",
    val ref: String = "",
) {
    val isHadith get() = type == TYPE_HADITH
    val isAyah get() = type == TYPE_AYAH
    val hasZikr get() = zikr.isNotBlank()
    val hasHiddenDetails get() = isnad.isNotBlank() || source.isNotBlank() || takhrij.isNotBlank() || notes.isNotEmpty()

    /** The main text shown big on the card. */
    val displayText: String
        get() = when {
            hasZikr -> zikr
            isAyah -> text
            isHadith -> matn
            else -> text
        }

    companion object {
        const val TYPE_HADITH = "hadith"
        const val TYPE_AYAH = "ayah"
        const val TYPE_TEXT = "text"
    }
}

/** A personal daily wird created by the user. */
@Serializable
data class Wird(
    val id: String,
    val text: String,
    val target: Int,
    /** When the wird was picked from the book, the id of that item (to show its source). */
    val itemId: String? = null,
)
